Haces **2 clics** en el botón de A. ¿Qué muestran los botones?

```jsx
function useContador() {
  const [n, setN] = useState(0);
  return [n, () => setN((x) => x + 1)];
}

function Boton({ etiqueta }) {
  const [n, sumar] = useContador();
  return <button onClick={sumar}>{etiqueta}: {n}</button>;
}

